2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"net/http"
8	
9		"github.com/entireio/cli/cmd/entire/cli/api"
10		"github.com/entireio/cli/cmd/entire/cli/auth"
11		"github.com/spf13/cobra"
12	)
13	
14	// tokenStore abstracts keyring access so commands that read or delete the
15	// stored bearer token can be unit-tested without hitting the real OS keyring.
16	// Used by logout and the auth subcommands.
17	type tokenStore interface {
18		GetToken(baseURL string) (string, error)
19		DeleteToken(baseURL string) error
20	}
21	
22	// revokeCurrentFunc revokes the CLI's current login session server-side.
23	// The caller resolves the active context's core URL + bearer up-front and
24	// binds them into the closure, so the revocation hits the same core that
25	// `auth status` lists.
26	type revokeCurrentFunc func(ctx context.Context) error
27	
28	// clearContextFunc removes the active contexts.json context (and its
29	// keyring token) so logout actually logs out under the contexts model.
30	// Injected so logout stays unit-testable without touching the real
31	// config dir.
32	type clearContextFunc func() error
33	
34	func newLogoutCmd() *cobra.Command {
35		var insecureHTTPAuth bool
36		var everywhere bool
